<script setup lang="ts">
import {can} from './session'
import {staErrorInfo} from './staErrors'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('StaPanel')

import {ref,reactive,computed,onMounted,onUnmounted,watch} from 'vue'
import {api,session} from './session'
import {ElMessageBox,ElMessage} from 'element-plus'
import ShipmentDeleteDialog from './ShipmentDeleteDialog.vue'
import {Loading} from '@element-plus/icons-vue'
const props=defineProps<{shippingId?:number,taskId?:string,active?:boolean}>();const emit=defineEmits(['created','completed'])
const task=ref<any>(null),shipping=ref<any>(null),error=ref(''),loading=ref(false),submitting=ref(false)
const admin=computed(()=>(can('shipping','operate')||can('fba.sta','operate')))
const address=reactive<Record<string,string>>({name:'',companyName:'',addressLine1:'',addressLine2:'',city:'',stateOrProvinceCode:'',countryCode:'CN',postalCode:'',phoneNumber:'',email:''})
const rawError=computed(()=>String(error.value||task.value?.error||''))
const errorInfo=computed(()=>staErrorInfo(rawError.value))
const addressRows=ref<any[]>([]),addressId=ref<number>(),addressBusy=ref(false)
const addressStore=computed(()=>task.value?.store||shipping.value?.store||'')
async function loadAddresses(){if(addressStore.value){const country=task.value?.country||shipping.value?.country||'';addressRows.value=await api('/sta/addresses?'+new URLSearchParams({store:addressStore.value,country}));if(!task.value){const preferred=addressRows.value.find(a=>a.country===country)||addressRows.value.find(a=>!a.country);if(preferred){addressId.value=preferred.id;Object.assign(address,preferred.detail)}}}}

function selectAddress(id:number){const a=addressRows.value.find(a=>a.id===id);if(a)Object.assign(address,a.detail)}
async function saveAddress(update=false){try{const label=update?addressRows.value.find(a=>a.id===addressId.value)?.label:(await ElMessageBox.prompt('为这个地址设置一个名称','保存发货地址',{inputPlaceholder:'例如：深圳发货仓'})).value;if(!label)return;addressBusy.value=true;const a=await api('/sta/addresses',{id:update?addressId.value:undefined,store:addressStore.value,label,detail:{...address}});await loadAddresses();addressId.value=a.id}catch(e){if(e instanceof Error)error.value=e.message}finally{addressBusy.value=false}}
async function deleteAddress(){try{await ElMessageBox.confirm('删除此保存地址？已创建货件中的地址保持不变。','删除地址');await api(`/sta/addresses/${addressId.value}/delete`,{});addressId.value=undefined;await loadAddresses()}catch(e){if(e instanceof Error)error.value=e.message}}
const addressLabels:Record<string,string>={name:'联系人',companyName:'公司名称',addressLine1:'街道地址',addressLine2:'地址补充',city:'城市',stateOrProvinceCode:'省 / 州',countryCode:'国家代码（如 CN）',postalCode:'邮编',phoneNumber:'联系电话',email:'联系邮箱'}
const form=reactive({name:'',mode:'packing_first',items:[] as any[]})
const names:Record<string,string>={draft:'待创建',queued:'后台排队中',running:'后台处理中',ready:'等待下一步',completed:'已完成',failed:'步骤失败',uncertain:'提交结果待核对',cancelled:'已删除'}
const stages=['create','packing','placement','delivery','labels','tracking']
const deleteDialog=ref(false)
const step=computed(()=>task.value?.status==='completed'?5:(({create:0,packing:1,placement:1,delivery:2,labels:3,tracking:4} as Record<string,number>)[task.value?.stage as string]??0))
const busy=computed(()=>submitting.value||['queued','running'].includes(task.value?.status))
const editable=computed(()=>admin.value&&!busy.value&&(!task.value||task.value.can_edit_creation))
const clock=ref(Date.now())
const idleSeconds=computed(()=>task.value?.updated_at?Math.max(0,Math.floor((clock.value-Date.parse(task.value.updated_at))/1000)):0)
const usable=computed(()=>admin.value&&!busy.value&&['ready','draft','completed'].includes(task.value?.status))
const result=computed(()=>task.value?.result||{})
const items=computed(()=>task.value?.snapshot.items||(shipping.value?.items||[]).filter((i:any)=>i.packed>0).map((i:any)=>({...i,quantity:i.packed})))
const boxes=computed(()=>task.value?.snapshot.boxes||shipping.value?.packing?.boxes||[])
const packingOptions=computed(()=>result.value.packingOptions||[])
const placementOptions=computed(()=>result.value.placementOptions||[])
const selectedPacking=ref(''),selectedPlacement=ref(''),assignments=reactive<Record<string,string>>({})
const currentPlacement=computed(()=>placementOptions.value.find((p:any)=>p.placementOptionId===selectedPlacement.value))
const shipments=computed(()=>(result.value.shipments||[]).filter((s:any)=>s.placementOptionId===result.value.placementConfirmed))
function shippingToday(){return new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Shanghai'})}
const shippingMethods=reactive<Record<string,string>>({}),deliveryFilters=reactive<Record<string,{solution:string,mode:string}>>({})
const readyDate=ref(shippingToday()),freight=reactive<Record<string,any>>({}),transport=reactive<Record<string,any>>({}),tracking=reactive<Record<string,any>>({})
const deliveryEditable=computed(()=>admin.value&&!busy.value&&task.value?.can_edit_delivery)
const deliverySelections=computed(()=>shipments.value.map((s:any)=>({shipmentId:s.shipmentId,deliveryWindowOptionId:transport[s.shipmentId]?.deliveryWindowOptionId||''})))
function windowValid(w:any){return !!w&&w.availabilityType!=='BLOCKED'&&Date.parse(w.startDate)<Date.parse(w.endDate)&&Date.parse(w.endDate)>clock.value&&(!w.validUntil||Date.parse(w.validUntil)>clock.value)&&(!readyDate.value||w.endDate.slice(0,10)>=readyDate.value)}
const windowsComplete=computed(()=>shipments.value.length>0&&deliverySelections.value.every((s:any)=>windowValid((result.value.deliveryWindows?.[s.shipmentId]||[]).find((w:any)=>w.deliveryWindowOptionId===s.deliveryWindowOptionId))))
const requestPayload=computed(()=>({readyDate:readyDate.value,freight:Object.fromEntries(shipments.value.map((s:any)=>[s.shipmentId,freight[s.shipmentId]])),selections:deliverySelections.value}))
function sameFreight(a:any,b:any){return ['declaredValue','pallets'].every(k=>Number(a?.[k]??0)===Number(b?.[k]??0))}
const carriersCurrent=computed(()=>{
 const old=result.value.transportRequest
 return !!old&&readyDate.value>=shippingToday()&&old.readyDate===readyDate.value&&deliverySelections.value.every((s:any)=>old.selections?.some((o:any)=>o.shipmentId===s.shipmentId&&o.deliveryWindowOptionId===s.deliveryWindowOptionId))&&shipments.value.every((s:any)=>sameFreight(old.freight?.[s.shipmentId],freight[s.shipmentId]))
})
const canGetCarriers=computed(()=>deliveryEditable.value&&!!readyDate.value&&readyDate.value>=shippingToday())
const canConfirmTransport=computed(()=>usable.value&&shipments.value.length>0&&carriersCurrent.value&&shipments.value.every((s:any)=>{const o=chosenCarrier(s.shipmentId);return !!o&&quoteValid(o)&&(!requiresWindow(o)||windowValid((result.value.deliveryWindows?.[s.shipmentId]||[]).find((w:any)=>w.deliveryWindowOptionId===transport[s.shipmentId]?.deliveryWindowOptionId)))}))
function windowLabel(w:any){return `${w.startDate?.slice(0,10)||''} 至 ${w.endDate?.slice(0,10)||''}${w.availabilityType==='BLOCKED'?'（不可用）':''}`}
function clearCarriers(){for(const s of shipments.value)if(transport[s.shipmentId])transport[s.shipmentId].transportationOptionId=''}
async function getCarriers(){if(!canGetCarriers.value)return;clearCarriers();await command('transport_options',requestPayload.value)}
const candidate=ref(''),labelType=ref('PackageLabel_A4_2'),downloading=reactive<Record<string,boolean>>({})
function fees(o:any){return [...(o.fees||[]).map((f:any)=>`费用 ${f.value?.amount??'—'} ${f.value?.code||''}`),...(o.discounts||[]).map((f:any)=>`优惠 ${f.value?.amount??'—'} ${f.value?.code||''}`)].join('；')||'未返回费用项目'}
function destination(s:any){const a=s.destination?.address||{};return [s.destination?.warehouseId,a.addressLine1,a.city,a.postalCode,a.countryCode].filter(Boolean).join(' · ')}
const modeLabels:Record<string,string>={GROUND_SMALL_PARCEL:'小包裹（SPD）',FREIGHT_LTL:'汽运零担（LTL）',FREIGHT_FTL_PALLET:'整车货运（托盘）',FREIGHT_FTL_NONPALLET:'整车货运（非托盘）',OCEAN_LCL:'海运拼箱',OCEAN_FCL:'海运整柜',AIR_SMALL_PARCEL:'空运小包',AIR_SMALL_PARCEL_EXPRESS:'空运快递'}
const solutionLabels:Record<string,string>={USE_YOUR_OWN_CARRIER:'自行安排承运人',AMAZON_PARTNERED_CARRIER:'亚马逊合作承运人'}
const methodLabels:Record<string,string>={air:'空运',sea:'海运',truck:'陆运'}
function shipmentOptions(sid:string){return (carriersCurrent.value?result.value.transportationOptions||[]:[]).filter((o:any)=>o.shipmentId===sid)}
function solutions(sid:string):string[]{return [...new Set<string>(shipmentOptions(sid).map((o:any)=>o.shippingSolution))]}
function carrierTypes(sid:string):string[]{return [...new Set<string>(shipmentOptions(sid).filter((o:any)=>o.shippingSolution===deliveryFilters[sid]?.solution).map((o:any)=>o.shippingMode))]}
function carrierOptions(sid:string){return shipmentOptions(sid).filter((o:any)=>o.shippingSolution===deliveryFilters[sid]?.solution&&o.shippingMode===deliveryFilters[sid]?.mode)}
function changeDeliveryFilter(sid:string,solution=false){transport[sid].transportationOptionId='';if(solution)deliveryFilters[sid].mode='';fillDeliveryChoices()}
function fillDeliveryChoices(){for(const s of shipments.value){const sid=s.shipmentId;deliveryFilters[sid]??={solution:'',mode:''};if(!carriersCurrent.value)continue;const f=deliveryFilters[sid],ss=solutions(sid);if(!ss.includes(f.solution))f.solution=ss.length===1?ss[0]:'';const modes=carrierTypes(sid);if(!modes.includes(f.mode))f.mode=modes.length===1?modes[0]:''}}
function shippingLabel(o:any){return [(o.carrier?.name?.toLowerCase()==='other'?'其他':o.carrier?.name)||'未返回名称',o.quote?.cost?`${o.quote.cost.amount} ${o.quote.cost.code}`:''].filter(Boolean).join(' · ')}
const previewCurrent=computed(()=>result.value.placementTransport?.request?.readyDate===readyDate.value)
function previewOptions(pid:string,sid:string){return previewCurrent.value?(result.value.placementTransport?.options?.[pid]||[]).filter((o:any)=>o.shipmentId===sid):[]}
function previewLoaded(pid:string){return previewCurrent.value&&Object.hasOwn(result.value.placementTransport?.options||{},pid)}
function placementType(s:any){return s.destination?.destinationType==='AMAZON_OPTIMIZED'?'亚马逊优化分仓':s.destination?.destinationType==='AMAZON_WAREHOUSE'?'指定亚马逊仓库':'亚马逊分仓'}
function requiresWindow(o:any){return o?.shippingSolution!=='AMAZON_PARTNERED_CARRIER'||o?.preconditions?.includes('CONFIRMED_DELIVERY_WINDOW')}
function chosenCarrier(sid:string){return carrierOptions(sid).find((o:any)=>o.transportationOptionId===transport[sid]?.transportationOptionId)}
function quoteValid(o:any){const q=o?.quote,c=q?.cost;return o?.shippingSolution!=='AMAZON_PARTNERED_CARRIER'||(c?.amount!=null&&Number.isFinite(Number(c.amount))&&Number(c.amount)>=0&&!!c.code&&(!q.expiration||Date.parse(q.expiration)>clock.value))}
function quoteText(o:any){if(o.shippingSolution!=='AMAZON_PARTNERED_CARRIER')return '运费与承运人自行结算';if(!o.quote?.cost)return '尚未返回报价';return `${o.quote.cost.amount} ${o.quote.cost.code}${quoteValid(o)?'':'（已过期，请重新获取）'}`}
function quoteExpiry(o:any){return o.quote?.expiration?`报价有效至 ${new Date(o.quote.expiration).toLocaleString('zh-CN')}`:''}
async function confirmDelivery(){const selections=shipments.value.map((s:any)=>{const o=chosenCarrier(s.shipmentId);return {...transport[s.shipmentId],deliveryWindowOptionId:requiresWindow(o)?transport[s.shipmentId].deliveryWindowOptionId:'',shippingMethod:shippingMethods[s.shipmentId],acceptedQuote:o?.quote?.cost}});const lines=shipments.value.map((s:any)=>{const o=chosenCarrier(s.shipmentId);return `${s.shipmentConfirmationId||destination(s)}：${solutionLabels[o.shippingSolution]} · ${o.carrier?.name||'承运人'} · ${quoteText(o)}`});await confirmed('transport',{selections},lines.join('；')+'。确认后将向亚马逊提交配送服务并接受上述合作承运人运费。')}
// Only the visible task may advance. Attempt keys prevent polling or failed requests from looping.
const automaticQuotes=new Set<string>(),automaticPlacements=new Set<string>()
let autoAdvancing=false
function panelActive(){return props.active!==false}
function automaticPlacement(){
 const options=placementOptions.value
 return options.length===1&&options[0].shipments?.length===1?options[0]:null
}
async function advancePlacement(){
 if(autoAdvancing||!panelActive()||loading.value||!usable.value||task.value?.stage!=='placement'||task.value.mode!=='packing_first'||!readyDate.value||readyDate.value<shippingToday())return
 const id=task.value.id,key=JSON.stringify([id,readyDate.value,placementOptions.value.map((o:any)=>o.placementOptionId)])
 if(!placementOptions.value.length)return
 autoAdvancing=true
 try{
  if(!placementOptions.value.every((o:any)=>previewLoaded(o.placementOptionId))){
   if(automaticQuotes.has(key))return
   automaticQuotes.add(key)
   await command('placement_transport_options',{readyDate:readyDate.value})
  }
  if(!panelActive()||!usable.value||task.value?.id!==id||task.value.stage!=='placement'||!placementOptions.value.every((o:any)=>previewLoaded(o.placementOptionId)))return
  const option=automaticPlacement()
  if(option&&!automaticPlacements.has(id+':'+option.placementOptionId)){
   automaticPlacements.add(id+':'+option.placementOptionId);selectedPlacement.value=option.placementOptionId
   await command('placement',{optionId:option.placementOptionId,boxAssignments:{}})
  }
 }finally{autoAdvancing=false}
}
watch([()=>task.value?.updated_at,()=>task.value?.status,()=>task.value?.stage,()=>props.active,readyDate,busy,loading],()=>{void advancePlacement()},{flush:'post'})
const carrierFeedback=computed(()=>{
 if(busy.value||!result.value.transportRequest)return null
 if(task.value?.status==='failed')return {type:'error' as const,text:'获取配送方案失败，请查看上方原因，修改后重新获取。'}
 if(!carriersCurrent.value)return {type:'warning' as const,text:'发货日期、送达时段或货运资料已变更，请重新获取承运人。'}
 const count=shipments.value.reduce((n:number,s:any)=>n+shipmentOptions(s.shipmentId).length,0)
 const partnered=(result.value.transportationOptions||[]).filter((o:any)=>o.shippingSolution==='AMAZON_PARTNERED_CARRIER').length
 return count?{type:(partnered?'success':'warning') as 'success'|'warning',text:`已获取 ${count} 个配送方案，其中 ${partnered} 个亚马逊合作承运人方案。${partnered?'选择合作承运人后核对运费。':'当前分仓未返回合作承运人报价；自行安排的 UPS 不属于亚马逊合作服务。'}`}:{type:'warning' as const,text:'获取已完成，但亚马逊未返回可用配送方案。请检查发货日期和货运资料后重新获取。'}
})
watch(()=>task.value?.status,(status,previous)=>{if(['queued','running'].includes(previous)&&status==='ready'&&task.value?.command?.action==='transport_options'){const count=result.value.transportationOptions?.length||0;if(count)ElMessage.success(`已获取 ${count} 个配送方案，请选择承运人类型和承运人`);else ElMessage.warning('亚马逊未返回可用配送方案，请检查资料后重试')}})
watch(()=>task.value?.status,(status,previous)=>{if(['queued','running'].includes(previous)&&['ready','completed'].includes(status)&&task.value?.command?.action==='rename')ElMessage.success('货件名称已同步亚马逊')})
watch(()=>task.value?.status,(status,previous)=>{if(['queued','running'].includes(previous)&&status==='completed'&&task.value?.command?.action==='tracking')ElMessage.success('全部货件追踪已提交，本地已标记完成');if(['queued','running'].includes(previous)&&status==='cancelled')ElMessage.success('货件已删除，库存处理已完成')})
async function renameShipment(s:any){try{const {value}=await ElMessageBox.prompt('保存后同步亚马逊货件名称，货件编号不变。','重命名货件',{inputValue:s.name||'',inputPlaceholder:'输入货件名称（最多 100 个字符）',confirmButtonText:'保存',cancelButtonText:'取消',inputValidator:(v:string)=>!!v?.trim()&&v.trim().length<=100&&!/[\x00-\x1f]/.test(v)||'请输入 1–100 个字符，不含换行'});if(value.trim()!==s.name)await command('rename',{shipmentId:s.shipmentId,name:value.trim()})}catch(e){if(e instanceof Error)error.value=e.message}}
function fillState(){for(const s of shipments.value){shippingMethods[s.shipmentId]??=result.value.deliveryDetails?.[s.shipmentId]?.shippingMethod||task.value.snapshot?.channel||'';freight[s.shipmentId]??={...(result.value.transportRequest?.freight?.[s.shipmentId]||{declaredValue:0,pallets:0})};transport[s.shipmentId]??={shipmentId:s.shipmentId,transportationOptionId:'',deliveryWindowOptionId:result.value.selectedDeliveryWindows?.[s.shipmentId]||''};const remote=s.trackingDetails||{},saved=result.value.trackingInputs?.[s.shipmentId];tracking[s.shipmentId]??=saved?{...saved,items:(saved.items||[]).map((x:any)=>({...x}))}:{shipmentId:s.shipmentId,type:remote.ltlTrackingDetail||result.value.deliveryDetails?.[s.shipmentId]?.shippingMode?.includes('FREIGHT')?'LTL':'SPD',freightBillNumber:remote.ltlTrackingDetail?.freightBillNumber?.[0]||'',billOfLadingNumber:remote.ltlTrackingDetail?.billOfLadingNumber||'',items:remote.spdTrackingDetail?.spdTrackingItems||[]};const old=tracking[s.shipmentId].items;tracking[s.shipmentId].items=(s.boxes||[]).filter((b:any)=>b.boxId).map((b:any)=>({boxId:b.boxId,trackingId:old.find((x:any)=>x.boxId===b.boxId)?.trackingId||''}))}fillDeliveryChoices()}
let polling=false
function hydrate(){form.name=task.value.name;form.mode=task.value.mode;Object.assign(address,task.value.form.sourceAddress);form.items=task.value.form.items.map((i:any)=>({sku:i.msku,labelOwner:i.labelOwner,prepOwner:i.prepOwner||'SELLER',expiration:i.expiration||null}));fillState()}
async function load(){if(polling||(!task.value?.id&&!props.taskId))return;polling=true;try{const next=await api('/sta/'+(task.value?.id||props.taskId));if(!task.value?.form)readyDate.value=next.result?.readyDate||next.result?.placementTransport?.request?.readyDate||shippingToday();const changed=!task.value?.form||task.value?.updated_at!==next.updated_at;task.value=next;if(changed)hydrate();error.value=''}catch(e){error.value='读取进度失败：'+(e as Error).message+'，正在重试；也可点击刷新本地进度。'}finally{polling=false}}
async function saveCreation(){submitting.value=true;error.value='';try{task.value=await api(`/sta/${task.value.id}/creation-settings`,{...form,sourceAddress:address,updated_at:task.value.updated_at});await command('create')}catch(e){error.value=(e as Error).message}finally{submitting.value=false}}

async function command(action:string,payload:any={}){if(action==='placement_options'){automaticQuotes.clear();automaticPlacements.clear()}submitting.value=true;error.value='';try{task.value=await api(`/sta/${task.value.id}/action`,{action,payload});hydrate()}catch(e){error.value=(e as Error).message}finally{submitting.value=false}}
async function create(){submitting.value=true;error.value='';try{if(!task.value){task.value=await api(`/sta/from-shipping/${props.shippingId}`,{...form,sourceAddress:address});emit('created',{id:task.value.id,name:task.value.name})}await command('create')}catch(e){error.value=(e as Error).message}finally{submitting.value=false}}
async function confirmed(action:string,payload:any={},message='确认将此步骤提交亚马逊？'){try{await ElMessageBox.confirm(message,'确认提交',{type:'warning',confirmButtonText:'确认提交'});await command(action,payload)}catch(e){if(e instanceof Error)error.value=e.message}}
async function download(s:any){if(downloading[s.shipmentId])return;downloading[s.shipmentId]=true;error.value='';try{const r=await fetch(`/api/sta/${task.value.id}/shipments/${s.shipmentId}/labels?page_type=${labelType.value}`);if(!r.ok){const d=await r.json();throw new Error(d.detail||'下载失败')}const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=decodeURIComponent(r.headers.get('Content-Disposition')?.match(/filename\*=UTF-8''(.+)/i)?.[1]||'')||`${task.value.shipping?.title||task.value.name}-${s.shipmentConfirmationId}-${s.boxes?.length||0}箱.pdf`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);ElMessage.success('箱子标签已生成并开始下载')}catch(e){error.value=(e as Error).message;ElMessage.error(staErrorInfo(error.value).title)}finally{downloading[s.shipmentId]=false}}
async function confirmDispatch(){if(!task.value?.can_confirm_dispatch||busy.value)return;const locked=task.value.shipping.inventory_status==='locked';try{await ElMessageBox.confirm(locked?`发货计划【${task.value.shipping.title}】完成发货？将按实际装箱记录出库并标记已完成。`:`发货计划【${task.value.shipping.title}】完成发货？库存未锁定，本次仅标记已完成，不扣库存。`,'完成发货',{type:'warning',confirmButtonText:'完成发货',cancelButtonText:'取消'});submitting.value=true;error.value='';task.value=await api(`/sta/${task.value.id}/confirm-dispatch`,{shipping_id:task.value.shipping.id,revision:task.value.shipping.revision});ElMessage.success(task.value.shipping.outbound_at?'已完成发货，库存已出库':'已完成发货，可稍后从发货计划出库');if(task.value.result?.dispatchCompleted)emit('completed')}catch(e){if(e instanceof Error){error.value=e.message;ElMessage.error(staErrorInfo(error.value).title)}}finally{submitting.value=false}}
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{loading.value=true;try{if(props.taskId)await load();else{shipping.value=await api(`/shipping/${props.shippingId}/detail`);if(shipping.value.sta){task.value={id:shipping.value.sta.id};await load()}else{form.name=String(shipping.value.title||shipping.value.number).slice(0,40);form.items=items.value.map((i:any)=>({sku:i.sku,labelOwner:'SELLER',prepOwner:'SELLER'}))}}await loadAddresses()}catch(e){error.value=(e as Error).message}finally{loading.value=false}timer=setInterval(()=>{clock.value=Date.now();if(task.value&&['queued','running'].includes(task.value.status))load()},2500)})
onUnmounted(()=>clearInterval(timer))
</script>
<template><div class="sta-page" v-loading="loading">
<div class="sta-toolbar"><div><b>{{task?.name||shipping?.title||'创建入库计划'}}</b><el-tag v-if="task">{{names[task.status]}}</el-tag><small>{{task?.store||shipping?.store}} · {{task?.country||shipping?.country}} · {{task?.inbound_plan_id||'未创建亚马逊计划'}}</small></div><div><el-button v-if="task" @click="load">刷新本地进度</el-button><el-button v-if="task" :disabled="busy||task.status==='cancelled'" @click="command('refresh')">同步亚马逊状态</el-button><el-button v-if="task&&admin" type="danger" plain :disabled="busy||task.status==='cancelled'" @click="deleteDialog=true">删除货件和费用</el-button></div></div>
<ShipmentDeleteDialog v-if="task" v-model="deleteDialog" :task-id="task.id" :name="task.name" @submitted="t=>task=t"/><el-steps :active="step" simple><el-step title="创建入库计划"/><el-step title="装箱与分仓"/><el-step title="配送服务"/><el-step title="箱子标签"/><el-step title="货件追踪"/></el-steps>
<section v-if="busy" class="sta-progress panel" role="status" aria-live="polite"><div class="sta-inline"><el-icon class="is-loading"><Loading/></el-icon><b>{{submitting?'正在提交任务…':task?.progress?.label||'正在后台处理…'}}</b></div><el-progress :percentage="task?.progress?.percent||0" :stroke-width="10"/><small>本次步骤进度 · 按后台操作阶段更新，等待亚马逊返回时百分比可能暂时不变。</small><p>离开此标签页不会中断任务。完成或失败后会自动更新，下方提交操作暂时锁定，防止重复创建。</p><p v-if="idleSeconds>60">已 {{idleSeconds}} 秒没有新进度，后台仍在排队或等待接口返回。可以点击“刷新本地进度”检查。</p></section>
<el-alert v-if="rawError" :type="errorInfo.type" :title="errorInfo.title" :closable="false" show-icon/>
<details v-if="rawError&&errorInfo.title!==rawError" class="sta-raw-error"><summary>技术详情</summary>{{rawError}}</details>
<div v-if="task?.status==='failed'&&!editable&&!task?.can_edit_delivery" class="sta-toolbar"><el-button :disabled="busy||!admin" type="primary" @click="command('retry')">继续重试失败步骤</el-button><span>已完成的提交不会重复执行；也可以取消后重建。</span></div>
<section v-if="task?.status==='uncertain'" class="panel sta-card"><b>请先在亚马逊核对任务</b><p>请求可能已成功。为避免创建重复货件，系统不会自动重复提交。</p><div v-if="!task.inbound_plan_id" class="sta-inline"><el-input v-model="candidate" placeholder="已核对的亚马逊入库计划 ID"/><el-button :disabled="busy||!admin" @click="command('reconcile',{inboundPlanId:candidate})">关联并核对</el-button></div><p v-else>可以同步状态，或取消该入库计划后重新创建。</p></section>
<section v-if="!task||task.stage==='create'" class="panel sta-card"><h3>入库计划设置</h3><el-form label-position="top" :disabled="!editable"><div class="sta-grid"><el-form-item label="计划名称（最多 40 字符）"><el-input v-model="form.name" maxlength="40" show-word-limit/></el-form-item></div><p>商品、数量及箱规取自已上传装箱单。</p><h4>发货地址</h4><p v-if="!addressRows.length">请先在设置 → FBA发货地址维护当前店铺与目的国的地址。</p><div class="sta-inline"><el-select v-model="addressId" placeholder="选择已保存的发货地址" clearable :disabled="!editable" @change="selectAddress"><el-option v-for="a in addressRows" :key="a.id" :value="a.id" :label="a.label"/></el-select></div><div class="sta-address"><el-form-item v-for="(label,key) in addressLabels" :key="key" :label="label" :error="errorInfo.fields[key]" :required="['name','addressLine1','city','countryCode','postalCode','phoneNumber'].includes(key)"><el-input v-model="address[key]" :placeholder="task?.form.sourceAddress[key]||''"/></el-form-item></div></el-form>
<template v-if="!task||task.stage==='create'"><TableReset table-key="StaPanel/table-1"/><el-table border data-width-key="StaPanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)"  :data="form.items"><el-table-column :column-key="'sku'" :width="tableWidths.width('table-1', 'sku', undefined)" prop="sku" label="SKU" min-width="240"/><el-table-column :column-key="'column-4'" :width="tableWidths.width('table-1', 'column-4', undefined)" label="有效期（适用时）"><template #default="{row}"><el-date-picker v-model="row.expiration" :disabled="!editable" type="date" value-format="YYYY-MM-DD" clearable/></template></el-table-column></el-table></template>
<div class="sta-toolbar"><el-button v-if="!task" type="primary" :loading="submitting" :disabled="busy||!admin||!shipping?.packing" @click="create">创建亚马逊入库计划</el-button><el-button v-else-if="task.can_edit_creation" type="primary" :loading="submitting" :disabled="busy||!admin" @click="saveCreation">保存修改并重新提交</el-button></div></section>
<section class="panel sta-card"><div class="sta-toolbar"><h3>商品与装箱单 <small>{{items.length}} 款 · {{boxes.length}} 箱</small></h3><TableReset table-key="StaPanel/table-2"/></div><template v-if="true"><el-table border data-width-key="StaPanel/table-2" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-2', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-2', column, event)" :data="items" max-height="320"><el-table-column :column-key="'sku'" :width="tableWidths.width('table-2', 'sku', undefined)" prop="sku" label="SKU" min-width="230"/><el-table-column :column-key="'fnsku'" prop="fnsku" label="FNSKU" :width="tableWidths.width('table-2', 'fnsku', '140')"/><el-table-column :column-key="'name'" :width="tableWidths.width('table-2', 'name', undefined)" prop="name" label="品名" min-width="200"/><el-table-column :column-key="'quantity'" prop="quantity" label="数量" :width="tableWidths.width('table-2', 'quantity', '90')" align="center"/></el-table></template><details open><summary>装箱内容及箱规 <span @click.stop><TableReset table-key="StaPanel/table-3"/></span></summary><template v-if="true"><el-table border data-width-key="StaPanel/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="boxes"><el-table-column :column-key="'column-1'" label="箱号" :width="tableWidths.width('table-3', 'column-1', '80')"><template #default="{row}">第{{row.number}}箱</template></el-table-column><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-3', 'column-2', undefined)" label="箱内商品" min-width="300"><template #default="{row}"><div v-for="i in row.items" :key="i.sku">{{i.sku}} × {{i.quantity}}</div></template></el-table-column><el-table-column :column-key="'weight_kg'" prop="weight_kg" label="重量 kg" :width="tableWidths.width('table-3', 'weight_kg', '110')" align="center"/><el-table-column :column-key="'column-4'" label="长×宽×高 cm" align="center" :width="tableWidths.width('table-3', 'column-4', '170')"><template #default="{row}">{{row.length_cm}} × {{row.width_cm}} × {{row.height_cm}}</template></el-table-column></el-table></template></details></section>
<section v-if="task?.stage==='packing'" class="panel sta-card"><h3>单装箱组方案</h3><p>保留原装箱单，只允许一个装箱组。亚马逊要求多组时，请取消并调整商品后重建。</p><div v-for="o in packingOptions" :key="o.packingOptionId" class="sta-option"><el-radio v-model="selectedPacking" :value="o.packingOptionId" :disabled="o.packingGroups.length!==1">{{o.packingGroups.length}} 个装箱组</el-radio><span>{{fees(o)}}</span></div><el-button type="primary" :disabled="!usable||!selectedPacking" @click="confirmed('packing',{optionId:selectedPacking},'确认使用此单装箱组方案，并提交所有箱规与装箱内容？请同时核对方案费用。')">确认装箱并获取分仓方案</el-button></section>
<section v-if="task?.stage==='placement'" class="panel sta-card"><h3>选择分仓方案</h3><div v-if="task.mode==='packing_first'" class="sta-inline"><label>发货日期</label><el-date-picker v-model="readyDate" value-format="YYYY-MM-DD" :disabled="!usable"/><el-button :disabled="!usable||!readyDate||readyDate<shippingToday()" @click="command('placement_transport_options',{readyDate})">重新获取运费</el-button></div><p v-if="task.mode==='packing_first'">承运人与运费自动加载。分仓费用不包含运输费用；合作承运人运费在下一步确认。</p><p v-else>当前为先分仓再装箱流程，提交装箱资料后才能查询承运人与运费。</p><div v-for="o in placementOptions" :key="o.placementOptionId" class="sta-option"><el-radio v-model="selectedPlacement" :value="o.placementOptionId">{{o.shipments?.length}} 个货件 · {{fees(o)}}</el-radio><div v-for="s in o.shipments" :key="s.shipmentId"><b>{{placementType(s)}} · {{destination(s)}}</b><small v-if="s.destination?.destinationType==='AMAZON_OPTIMIZED'">实际配送地址以亚马逊标签为准。</small><small>{{s.items?.map((i:any)=>i.msku+' × '+i.quantity).join('；')}}</small><div v-if="task.mode==='packing_first'" class="sta-preview"><template v-if="previewLoaded(o.placementOptionId)"><div v-for="q in previewOptions(o.placementOptionId,s.shipmentId).filter((q:any)=>q.shippingSolution==='AMAZON_PARTNERED_CARRIER')" :key="q.transportationOptionId" class="sta-quote"><strong>亚马逊合作承运人 · {{q.carrier?.name}} · {{modeLabels[q.shippingMode]||q.shippingMode}}</strong><span>{{quoteText(q)}}</span><small>{{quoteExpiry(q)}}</small></div><p v-if="!previewOptions(o.placementOptionId,s.shipmentId).some((q:any)=>q.shippingSolution==='AMAZON_PARTNERED_CARRIER')">该方案未返回亚马逊合作承运人报价。</p><small v-if="previewOptions(o.placementOptionId,s.shipmentId).some((q:any)=>q.shippingSolution==='USE_YOUR_OWN_CARRIER')">支持自行安排承运人，运费另行结算。</small></template><p v-else>正在自动获取该方案的承运人与运费。</p></div></div></div><div v-if="task.mode==='placement_first'&&currentPlacement"><h4>按原整箱分配到货件</h4><p>每个箱子只能分配给一个货件；分配数量必须和亚马逊要求一致。</p><div class="sta-inline" v-for="b in boxes" :key="b.number"><b>第 {{b.number}} 箱</b><el-select v-model="assignments[String(b.number)]" placeholder="选择收货仓"><el-option v-for="s in currentPlacement.shipments" :key="s.shipmentId" :value="s.shipmentId" :label="destination(s)"/></el-select></div></div><div class="sta-toolbar"><el-button :disabled="!usable" @click="command('placement_options')">重新获取方案</el-button><el-button type="primary" :disabled="!usable||!selectedPlacement||(task.mode==='packing_first'&&!previewLoaded(selectedPlacement))" @click="confirmed('placement',{optionId:selectedPlacement,boxAssignments:assignments},'确认此分仓方案及显示的费用？确认后将按亚马逊分仓结果生成货件。')">确认分仓</el-button></div></section>
<section v-if="task&&stages.indexOf(task.stage)>=3" class="panel sta-card"><h3>货件与配送服务</h3><el-alert v-if="task.stage==='delivery'&&carrierFeedback" class="sta-carrier-feedback" :title="carrierFeedback.text" :type="carrierFeedback.type" :closable="false" show-icon/><div v-if="task.stage==='delivery'" class="sta-delivery-date"><label for="sta-ready-date">发货日期</label><el-date-picker id="sta-ready-date" v-model="readyDate" value-format="YYYY-MM-DD" placeholder="默认今天" :disabled="!deliveryEditable" @change="clearCarriers"/><small>默认今天，可按实际发货安排修改。</small></div><div v-for="s in shipments" :key="s.shipmentId" class="sta-option"><div class="sta-shipment-heading"><b>{{s.shipmentConfirmationId||s.shipmentId}}</b><el-button v-if="admin&&s.shipmentConfirmationId" link type="primary" :disabled="!usable" @click="renameShipment(s)">重命名货件</el-button></div><p v-if="s.name" class="sta-shipment-name">{{s.name}}</p><p>{{destination(s)}}</p><small>Reference ID：{{s.amazonReferenceId||'待返回'}} · {{s.status}}</small><div v-if="task.stage==='delivery'">
<div class="sta-delivery-grid">
<div v-if="deliveryFilters[s.shipmentId]?.solution!=='AMAZON_PARTNERED_CARRIER'||requiresWindow(chosenCarrier(s.shipmentId)||{shippingSolution:'AMAZON_PARTNERED_CARRIER'})" class="sta-delivery-field"><label :for="'window-'+s.shipmentId">送达时段（自行安排承运人必填）</label>
<el-select :id="'window-'+s.shipmentId" v-model="transport[s.shipmentId].deliveryWindowOptionId" :disabled="!deliveryEditable" placeholder="选择送达时段" @change="clearCarriers"><el-option v-for="w in result.deliveryWindows?.[s.shipmentId]||[]" :key="w.deliveryWindowOptionId" :value="w.deliveryWindowOptionId" :label="windowLabel(w)" :disabled="!windowValid(w)"/></el-select>
<small v-if="!result.deliveryWindows?.[s.shipmentId]?.length">暂无时段，请点击“获取可选送达时段”。</small></div>
<div class="sta-delivery-field"><label :for="'solution-'+s.shipmentId">配送模式</label><el-select :id="'solution-'+s.shipmentId" v-model="deliveryFilters[s.shipmentId].solution" :disabled="!usable||!carriersCurrent" placeholder="选择配送模式" @change="changeDeliveryFilter(s.shipmentId,true)"><el-option v-for="v in solutions(s.shipmentId)" :key="v" :value="v" :label="solutionLabels[v]||v"/></el-select></div>
<div class="sta-delivery-field"><label :for="'type-'+s.shipmentId">承运人类型</label><el-select :id="'type-'+s.shipmentId" v-model="deliveryFilters[s.shipmentId].mode" :disabled="!usable||!carriersCurrent||!deliveryFilters[s.shipmentId].solution" placeholder="选择承运人类型" @change="changeDeliveryFilter(s.shipmentId)"><el-option v-for="v in carrierTypes(s.shipmentId)" :key="v" :value="v" :label="modeLabels[v]||v"/></el-select></div>
<div class="sta-delivery-field"><label :for="'method-'+s.shipmentId">运输方式</label><el-select :id="'method-'+s.shipmentId" v-model="shippingMethods[s.shipmentId]" :disabled="!deliveryEditable" placeholder="选择运输方式"><el-option v-for="(label,value) in methodLabels" :key="value" :value="value" :label="label"/></el-select></div>
<div class="sta-delivery-field"><label :for="'carrier-'+s.shipmentId">承运人</label><el-select :id="'carrier-'+s.shipmentId" v-model="transport[s.shipmentId].transportationOptionId" :disabled="!usable||!carriersCurrent||!deliveryFilters[s.shipmentId].mode" placeholder="先选择承运人类型"><el-option v-for="o in carrierOptions(s.shipmentId)" :key="o.transportationOptionId" :value="o.transportationOptionId" :label="shippingLabel(o)"/></el-select></div>
<div v-if="chosenCarrier(s.shipmentId)" class="sta-quote sta-option-help"><strong>{{solutionLabels[chosenCarrier(s.shipmentId).shippingSolution]}} · {{quoteText(chosenCarrier(s.shipmentId))}}</strong><small>{{quoteExpiry(chosenCarrier(s.shipmentId))}}</small></div>
<p class="sta-option-help" v-if="carriersCurrent&&!shipmentOptions(s.shipmentId).length">该货件没有可用配送方案，请检查资料后重新获取。</p>

</div>
<div class="sta-freight-grid"><div class="sta-delivery-field"><label>申报货值 {{task.country==='UK'?'GBP':'EUR'}}</label><el-input-number v-model="freight[s.shipmentId].declaredValue" :min="0" :disabled="!deliveryEditable" @change="clearCarriers"/></div><div class="sta-delivery-field"><label>托盘数（小包留 0）</label><el-input-number v-model="freight[s.shipmentId].pallets" :min="0" :precision="0" :disabled="!deliveryEditable" @change="clearCarriers"/></div></div>
</div><div v-else><p>已确认配送服务 · {{result.readyDate}}</p><div v-if="result.deliveryDetails?.[s.shipmentId]" class="sta-delivery-summary"><span>配送模式：{{solutionLabels[result.deliveryDetails[s.shipmentId].shippingSolution]||result.deliveryDetails[s.shipmentId].shippingSolution}}</span><span>承运人类型：{{modeLabels[result.deliveryDetails[s.shipmentId].shippingMode]||result.deliveryDetails[s.shipmentId].shippingMode}}</span><span>运输方式：{{methodLabels[result.deliveryDetails[s.shipmentId].shippingMethod]||'未填写'}}</span><span>承运人：{{shippingLabel(result.deliveryDetails[s.shipmentId])}}</span></div><el-select v-model="labelType" style="width:250px"><el-option value="PackageLabel_A4_4" label="A4 每页 4 个箱标签"/><el-option value="PackageLabel_A4_2" label="A4 每页 2 个箱标签"/><el-option value="PackageLabel_Thermal_NonPCP" label="热敏箱标签"/></el-select><el-button :loading="downloading[s.shipmentId]" @click="download(s)">下载亚马逊箱子标签</el-button><p v-if="labelType==='PackageLabel_A4_2'&&result.deliveryDetails?.[s.shipmentId]?.shippingSolution==='USE_YOUR_OWN_CARRIER'" class="sta-label-hint">使用亚马逊原始箱标签，排列为 A4 每页两张。打印请选择实际大小（100%）。</p><details><summary>填写货件追踪（可稍后填写）</summary><p class="sta-label-hint">物流编号生成后，可从发货计划的“查看货件”进入补填或修改。</p><el-radio-group v-model="tracking[s.shipmentId].type"><el-radio value="SPD">小包裹追踪</el-radio><el-radio value="LTL">零担 / 整车货运</el-radio></el-radio-group><template v-if="tracking[s.shipmentId].type==='SPD'"><div v-for="b in tracking[s.shipmentId].items" :key="b.boxId" class="sta-inline"><span>{{b.boxId}}</span><el-input v-model="b.trackingId" placeholder="追踪编码"/></div></template><div v-else class="sta-inline"><el-input v-model="tracking[s.shipmentId].freightBillNumber" placeholder="货运单号"/><el-input v-model="tracking[s.shipmentId].billOfLadingNumber" placeholder="提单号（可选）"/></div><el-button type="primary" :disabled="!usable" @click="confirmed('tracking',tracking[s.shipmentId])">提交追踪信息</el-button></details></div></div><template v-if="task.stage==='delivery'"><p>先获取承运人并核对运费。自行安排承运人需选择送达时段；合作承运人按返回方案要求填写。修改发货日期、送达时段或货运资料后，需重新获取报价。</p><div class="sta-toolbar sta-delivery-actions"><el-button :disabled="!deliveryEditable" @click="clearCarriers();command('delivery_windows')">获取可选送达时段</el-button><el-button :disabled="!canGetCarriers" @click="getCarriers">获取承运人</el-button><el-button type="primary" :disabled="!canConfirmTransport" @click="confirmDelivery">确认配送服务</el-button></div></template></section>
<details v-if="task" class="panel sta-card"><summary>步骤记录</summary><p>每次提交及亚马逊操作编号保存在本地，方便失败排查。</p><div v-for="(j,key) in task.journal" :key="key">{{key}} · {{(j as any).state}} · {{(j as any).operationId||''}}</div><div v-for="(h,n) in result.history||[]" :key="n">{{h.at}} · {{h.command?.action||'初始'}} · {{h.status}}</div></details>
<section v-if="task&&result.transportConfirmed&&['labels','tracking'].includes(task.stage)&&task.status!=='cancelled'" class="panel sta-dispatch-confirm"><div><b>{{result.dispatchCompleted?'已完成发货':'配送服务已完成，可以完成发货'}}</b><p v-if="task.shipping?.outbound_at">库存已出库，追踪编码可稍后补填或修改。</p><p v-else-if="task.shipping?.inventory_status==='locked'">完成发货时按装箱记录出库，追踪编码可稍后填写。</p><p v-else>完成发货仅标记已完成，不扣库存；稍后可在发货计划中出库。</p></div><el-button v-if="admin" type="primary" size="large" :disabled="!task.can_confirm_dispatch||busy" :loading="submitting" @click="confirmDispatch">{{result.dispatchCompleted?'已完成发货':'完成发货'}}</el-button></section></div>
</template>
<style scoped>
.sta-preview{margin-top:14px}.sta-quote{padding:12px 16px;background:#edf7f2;border-radius:6px;display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin:8px 0}.sta-quote strong{color:#217865}.sta-quote span{font-weight:600}.sta-quote small{margin:0}

.sta-delivery-summary{display:grid;grid-template-columns:1fr 1fr;gap:14px}.sta-option-help{grid-column:1/-1}.sta-carrier-feedback{margin-bottom:18px}
.sta-delivery-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px;margin:20px 0}
.sta-delivery-field{display:flex;flex-direction:column;gap:9px;min-width:0}.sta-delivery-field>label{font-size:14px;font-weight:500;color:#43594f}.sta-delivery-field .el-select{width:100%}
